use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{collections::BTreeMap,fs,fmt::Write,path::{Path,PathBuf},process::{Command,Stdio}};
const R:&str="/home/ubuntu/src/zopro-perf-work/solver-a-stream176";const O:&str="/home/ubuntu/src/zk-tools/zopro/docs/benchmarks/2026-11-06-solver-a-stream176";
fn hash(b:&[u8])->String{format!("{:x}",Sha256::digest(b))}fn walk(p:&Path)->Vec<PathBuf>{let mut v=vec![];for e in fs::read_dir(p).unwrap(){let p=e.unwrap().path();if p.is_dir(){v.extend(walk(&p))}else{v.push(p)}}v.sort();v}
fn main(){let out=Path::new(O);let archive=out.join("artifacts/receipts-and-helpers.json.gz");let old=Command::new("gzip").args(["-d","-c"]).arg(&archive).output().unwrap();assert!(old.status.success());let mut members: BTreeMap<String,Value>=serde_json::from_slice(&old.stdout).unwrap();let previous=members.len();
 for f in["driver/Cargo.toml","driver/Cargo.lock","publication-complete.rs"]{let p=format!("{R}/{f}");let b=fs::read(&p).unwrap();members.insert(p,json!({"utf8":String::from_utf8(b.clone()).unwrap(),"length":b.len(),"sha256":hash(&b)}));}
 let bytes=serde_json::to_vec(&members).unwrap();let temporary=out.join("artifacts/receipts.temporary");fs::write(&temporary,&bytes).unwrap();assert!(Command::new("gzip").args(["-n","-c"]).arg(&temporary).stdout(Stdio::from(fs::File::create(&archive).unwrap())).status().unwrap().success());let restored=Command::new("gzip").args(["-d","-c"]).arg(&archive).output().unwrap();assert!(restored.status.success());assert_eq!(restored.stdout,bytes);fs::remove_file(temporary).unwrap();
 let full=fs::read(format!("{R}/analysis.json")).unwrap();let mut compact:Value=serde_json::from_slice(&full).unwrap();assert!(compact.as_object_mut().unwrap().remove("caller_receipts").is_some());compact["full_analysis_archive_member"]=json!(format!("{R}/analysis.json"));compact["full_analysis_sha256"]=json!(hash(&full));fs::write(out.join("artifacts/analysis.json"),serde_json::to_vec_pretty(&compact).unwrap()).unwrap();
 let delivery=json!({"original_publication_members":previous,"receipt_archive_members":members.len(),"source_archive_files":179,"raw_profiles":4,"all_archive_bytes_roundtrip_checked":true,"full_analysis_original_bytes_archived":true,"full_analysis_sha256":hash(&full),"compact_public_analysis_omits_only_duplicated_caller_receipts":true,"driver_manifest_and_lock_archived":true,"reproduction":"Run publish.rs, then publication-complete.rs; no benchmark or tests repeated."});fs::write(out.join("artifacts/delivery.json"),serde_json::to_vec_pretty(&delivery).unwrap()).unwrap();fs::copy(format!("{R}/publication-complete.rs"),out.join("artifacts/publication-complete.rs")).unwrap();
 let mut sums=String::new();for p in walk(out){if p.file_name().unwrap()=="SHA256SUMS"{continue;}writeln!(sums,"{}  {}",hash(&fs::read(&p).unwrap()),p.strip_prefix(out).unwrap().display()).unwrap();}fs::write(out.join("SHA256SUMS"),sums).unwrap();println!("Completed395UTF8members incl exact driver manifest/lock; compact public analysis retains full original analysis bytes in archive; no tests/captures repeated.");}
